"use client";

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/**
 * Unified destructive section-error card with an optional retry affordance.
 * Replaces the repeated `border-destructive/… bg-destructive/…` blocks so
 * failure states read consistently and can offer a one-click retry.
 */
export function SectionError({
  title = "Something went wrong",
  description,
  onRetry,
  className,
}: {
  title?: string;
  description?: ReactNode;
  onRetry?: () => void;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-3 rounded-lg border border-destructive/40 bg-destructive/10 p-6 text-center",
        className,
      )}
    >
      <div>
        <p className="text-sm font-medium text-foreground">{title}</p>
        {description && <p className="mt-1 text-sm text-muted-foreground">{description}</p>}
      </div>
      {onRetry && (
        <button
          type="button"
          onClick={onRetry}
          className="rounded-md border border-border bg-background px-3 py-1.5 text-sm font-medium text-foreground transition-colors hover:bg-accent"
        >
          Retry
        </button>
      )}
    </div>
  );
}
